## 🎯 Dans cette leçon

Le **bouton poussoir** ferme un circuit **seulement pendant l'appui**. C'est la commande la plus simple pour envoyer un ordre à une carte : marche, arrêt, valider, changer de mode.

À la fin de cette leçon, tu sauras :

- repérer les pattes d'un bouton à 4 pattes ;
- câbler un bouton **sans résistance** avec `INPUT_PULLUP` ;
- expliquer pourquoi une entrée « en l'air » lit n'importe quoi ;
- comprendre les **rebonds** et les filtrer ;
- détecter un appui (un changement d'état) plutôt qu'un état.

blocs.code:
// Leçon 6.1 — la LED change d'état à chaque appui
const int BOUTON = 2, LED = 13;   // bouton -> GND, LED + 220 Ω -> GND
bool led = false;
int avant = HIGH;                  // état précédent du bouton

void setup() {
  pinMode(BOUTON, INPUT_PULLUP);   // résistance de tirage interne
  pinMode(LED, OUTPUT);
}

void loop() {
  int etat = digitalRead(BOUTON);
  if (etat != avant) {             // le bouton a changé
    if (etat == LOW) led = !led;   // appui (front descendant) : on bascule
    digitalWrite(LED, led);
    delay(50);                     // anti-rebond simple
    avant = etat;
  }
}

// Solution du mini-défi : deux boutons (marche / arrêt) et compteur d'appuis
const int MARCHE = 2, ARRET = 3, LED = 13;
int avantM = HIGH, avantA = HIGH;
unsigned long appuis = 0;

void setup() {
  pinMode(MARCHE, INPUT_PULLUP);
  pinMode(ARRET, INPUT_PULLUP);
  pinMode(LED, OUTPUT);
  Serial.begin(9600);
}

void loop() {
  int m = digitalRead(MARCHE), a = digitalRead(ARRET);
  if (m != avantM || a != avantA) {          // un des boutons a changé
    if (m == LOW && avantM == HIGH) { digitalWrite(LED, HIGH); appuis++; }
    if (a == LOW && avantA == HIGH) { digitalWrite(LED, LOW);  appuis++; }
    Serial.print("Appuis : "); Serial.println(appuis);
    delay(50);                                 // anti-rebond
    avantM = m; avantA = a;
  }
}

