## 🎯 Dans cette leçon

Contrairement au poussoir, un **interrupteur garde sa position** : ouvert ou fermé, sans qu'on le tienne. Il sert à mettre sous tension, à choisir un mode ou à détecter une position (porte, fin de course).

À la fin de cette leçon, tu sauras :

- lire les sigles SPST, SPDT, DPDT, NO et NC ;
- trouver le commun d'un inverseur au multimètre ;
- lire un interrupteur avec `INPUT_PULLUP` ;
- détecter une porte avec un ILS et un aimant ;
- calculer le nombre de combinaisons d'un interrupteur DIP.

blocs.code:
// Leçon 6.2 — surveiller une porte avec un ILS
const int ILS = 2, LED = 13;   // ILS -> GND, LED + 220 Ω -> GND
int avant = -1;                // dernier état affiché (-1 : aucun)

void setup() {
  Serial.begin(9600);
  pinMode(ILS, INPUT_PULLUP);   // résistance de tirage interne
  pinMode(LED, OUTPUT);
}

void loop() {
  int etat = digitalRead(ILS);   // LOW = aimant proche = porte fermée
  digitalWrite(LED, etat);       // LED allumée si la porte est ouverte
  if (etat != avant) {           // on n'affiche que les changements
    Serial.println(etat ? "Ouverte" : "Fermée");
    avant = etat;
    delay(20);                   // anti-rebond
  }
}

// Solution du mini-défi : alarme de porte avec 3 bips et compteur
const int ILS = 2, LED = 13, BUZZER = 8;
int avant = LOW;
unsigned int ouvertures = 0;

void setup() {
  Serial.begin(9600);
  pinMode(ILS, INPUT_PULLUP);
  pinMode(LED, OUTPUT);
}

void loop() {
  int etat = digitalRead(ILS);
  digitalWrite(LED, etat);
  if (etat == HIGH && avant == LOW) {        // la porte vient de s'ouvrir
    ouvertures++;
    Serial.print("Ouverture n° "); Serial.println(ouvertures);
    for (int i = 0; i < 3; i++) {
      tone(BUZZER, 2000, 150);                  // bip de 150 ms à 2 kHz
      delay(300);
    }
  }
  if (etat != avant) delay(20);                 // anti-rebond
  avant = etat;
}

