## 🎯 Dans cette leçon

Seize boutons séparés demanderaient 16 broches. Le **clavier matriciel** range ses touches en **4 lignes et 4 colonnes** : 8 fils suffisent. C'est la base d'une serrure électronique, d'une alarme ou d'un menu.

À la fin de cette leçon, tu sauras :

- expliquer comment un appui relie une ligne à une colonne ;
- calculer le nombre de fils d'un clavier matriciel ;
- comprendre le **balayage** des colonnes ;
- utiliser la bibliothèque Keypad et `getKey()` ;
- programmer un digicode avec validation et effacement.

blocs.code:
// Leçon 6.3 — digicode à 4 chiffres avec la bibliothèque Keypad
#include <Keypad.h>

char touches[4][4] = {{'1','2','3','A'},
                      {'4','5','6','B'},
                      {'7','8','9','C'},
                      {'*','0','#','D'}};
byte lignes[4]   = {9, 8, 7, 6};    // L1 à L4
byte colonnes[4] = {5, 4, 3, 2};    // C1 à C4
Keypad clavier(makeKeymap(touches), lignes, colonnes, 4, 4);

const String CODE = "1234";
String saisie = "";

void setup() {
  pinMode(13, OUTPUT);
  Serial.begin(9600);
}

void loop() {
  char t = clavier.getKey();          // 0 si aucune touche
  if (!t) return;
  Serial.print(t);
  if (t == '*') {                     // effacer
    saisie = "";
    Serial.println("  (effacé)");
  } else if (t == '#') {              // valider
    bool bon = (saisie == CODE);
    digitalWrite(13, bon);
    Serial.println(bon ? "  CODE BON" : "  code faux");
    saisie = "";
  } else {
    saisie += t;                      // ajouter le caractère
  }
}

// Solution du mini-défi : bips et blocage après 3 erreurs
#include <Keypad.h>
char touches[4][4] = {{'1','2','3','A'},{'4','5','6','B'},{'7','8','9','C'},{'*','0','#','D'}};
byte lignes[4] = {9, 8, 7, 6}, colonnes[4] = {5, 4, 3, 2};
Keypad clavier(makeKeymap(touches), lignes, colonnes, 4, 4);
const int LED = 13, BUZZER = 10;
const String CODE = "1234";
String saisie = "";
int erreurs = 0;

void setup() { pinMode(LED, OUTPUT); }

void loop() {
  char t = clavier.getKey();
  if (!t) return;
  tone(BUZZER, 2500, 40);                     // bip court à chaque touche
  if (t == '*') { saisie = ""; return; }
  if (t != '#') { saisie += t; return; }
  if (saisie == CODE) {
    digitalWrite(LED, HIGH); erreurs = 0;
  } else {
    digitalWrite(LED, LOW); erreurs++;
    for (int i = 0; i < 3; i++) { tone(BUZZER, 600, 150); delay(250); }
    if (erreurs >= 3) {                       // blocage de 30 s
      delay(30000);                           // ici, bloquer est voulu
      erreurs = 0;
    }
  }
  saisie = "";
}

