## 🎯 Dans cette leçon

Un **encodeur rotatif** ressemble à un potentiomètre, mais il tourne **sans fin**, par **crans** réguliers. Il ne donne pas une position : il signale chaque cran et son **sens**. Le programme tient le compte.

À la fin de cette leçon, tu sauras :

- distinguer un encodeur d'un potentiomètre ;
- lire deux signaux en **quadrature** et en déduire le sens ;
- compter les crans sans en compter deux fois trop ;
- calculer un angle et une vitesse de rotation ;
- lire le bouton intégré à l'axe.

blocs.code:
// Leçon 6.4 — compter les crans d'un encodeur KY-040
const int CLK = 2, DT = 3, SW = 4;
int compteur = 0;
int avant;                        // état précédent de CLK

void setup() {
  Serial.begin(9600);
  pinMode(CLK, INPUT);            // pull-up déjà sur le module
  pinMode(DT, INPUT);
  pinMode(SW, INPUT_PULLUP);      // le bouton n'a pas de pull-up
  avant = digitalRead(CLK);
}

void loop() {
  int etat = digitalRead(CLK);
  if (etat != avant && etat == LOW) {        // un seul front par cran
    compteur += digitalRead(DT) ? 1 : -1;    // DT donne le sens
    Serial.print(compteur);
    Serial.print("  ("); Serial.print(compteur * 18); Serial.println("°)");
  }
  avant = etat;
  if (digitalRead(SW) == LOW) {               // appui sur l'axe
    compteur = 0;
    Serial.println("remise à zéro");
    delay(200);
  }
}

// Solution du mini-défi : réglage de 0 à 100 sur LCD I2C, pas de 1 ou 10
#include <LiquidCrystal_I2C.h>          // bibliothèque « LiquidCrystal I2C »
LiquidCrystal_I2C lcd(0x27, 16, 2);      // adresse 0x27 (ou 0x3F)
const int CLK = 2, DT = 3, SW = 4;
int valeur = 50, pas = 1, avant;

void afficher() {
  lcd.clear();
  lcd.print("Valeur : "); lcd.print(valeur);
  lcd.setCursor(0, 1);
  lcd.print("Pas : "); lcd.print(pas);
}

void setup() {
  pinMode(SW, INPUT_PULLUP);
  lcd.init(); lcd.backlight();
  avant = digitalRead(CLK);
  afficher();
}

void loop() {
  int etat = digitalRead(CLK);
  if (etat != avant && etat == LOW) {
    valeur += digitalRead(DT) ? pas : -pas;
    valeur = constrain(valeur, 0, 100);   // bornes 0 et 100
    afficher();
  }
  avant = etat;
  if (digitalRead(SW) == LOW) {
    pas = (pas == 1) ? 10 : 1;            // bascule entre 1 et 10
    afficher();
    while (digitalRead(SW) == LOW) { }    // attendre le relâchement
    delay(50);
  }
}

