## 🎯 Dans cette leçon

Un **joystick** réunit deux potentiomètres de 10 kΩ (un par axe) et un bouton poussoir sous un manche. Il sert à piloter un robot, une tourelle, un curseur ou un menu.

À la fin de cette leçon, tu sauras :

- lire les axes X et Y avec `analogRead()` ;
- convertir une lecture en tension et en écart par rapport au centre ;
- prévoir une **zone morte** autour du repos ;
- transformer une position en vitesse ou en angle avec `map()` ;
- lire le clic avec `INPUT_PULLUP`.

blocs.code:
// Leçon 6.5 — lire la direction d'un joystick KY-023
const int VRX = A0, VRY = A1, SW = 2;
const int ZONE = 100;                 // zone morte autour du centre

void setup() {
  Serial.begin(9600);
  pinMode(SW, INPUT_PULLUP);          // pas de pull-up sur le module
}

void loop() {
  int x = analogRead(VRX) - 512;      // de -512 à +511
  int y = analogRead(VRY) - 512;
  Serial.print("x="); Serial.print(x);
  Serial.print(" y="); Serial.print(y); Serial.print("  ");
  if (x < -ZONE)      Serial.print("Gauche ");
  else if (x > ZONE)  Serial.print("Droite ");
  if (y < -ZONE)      Serial.print("Haut ");
  else if (y > ZONE)  Serial.print("Bas ");
  if (digitalRead(SW) == LOW) Serial.print("Clic");
  Serial.println();
  delay(200);
}

// Solution du mini-défi : tourelle à deux servos (pan / tilt)
#include <Servo.h>
Servo panoramique, inclinaison;
const int VRX = A0, VRY = A1, SW = 2;

void setup() {
  panoramique.attach(9);     // servo X sur D9
  inclinaison.attach(10);    // servo Y sur D10
  pinMode(SW, INPUT_PULLUP);
}

void loop() {
  if (digitalRead(SW) == LOW) {             // clic : retour au centre
    panoramique.write(90);
    inclinaison.write(90);
    delay(300);
    return;
  }
  panoramique.write(map(analogRead(VRX), 0, 1023, 0, 180));
  inclinaison.write(map(analogRead(VRY), 0, 1023, 0, 180));
  delay(15);                                // laisser le temps aux servos
}

// Les servos sont alimentés par une source 5 V séparée,
// dont le GND est relié à celui de l'Arduino.

